# Builds site/data/tracks/12-tpm.js: runs every step of steps12.py in order, as one Python file,
# against the canonical sample database on SQL Server (BC_SQL_PASSWORD and the container from
# sql_exec.py), and records what each step prints as its output. Do not edit the JS file by hand.
#   python3 build12.py            write the track
#   python3 build12.py --check    report a difference, change nothing
import contextlib, io, json, os, re, subprocess, sys, tempfile, warnings
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE.parent / "lib" / "pydb"))
import plantdb
from steps12 import CODE
from lessons12 import TRACK, LESSONS

plantdb.reset()
plantdb.use_real_database()
warnings.filterwarnings("ignore", message="pandas only supports SQLAlchemy")
assert [t for t, *_ in LESSONS] == list(CODE), "lessons12.py and steps12.py list different steps"

outs, g = {}, {}
with tempfile.TemporaryDirectory() as d:
    os.chdir(d)  # the A3 step saves an .xlsx
    for title, *_ in LESSONS:
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            exec(CODE[title], g)
        outs[title] = buf.getvalue().rstrip()

def whole(k, code):
    pre = r"(?<!\w)" if re.match(r"\w", k) else ""
    post = r"(?!\w)" if re.search(r"\w$", k) else ""
    return re.search(pre + re.escape(k) + post, code) is not None

tpl = lambda x: "`" + x.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${") + "`"
js = lambda v: json.dumps(v, ensure_ascii=False)
lines = ["// Project track 12: TPM Loss Hunt (Python on the plant database)",
         "// Generated by tools/output-checks/track12-tpm/build12.py from steps12.py and lessons12.py. Do not edit by hand.",
         "BC.addTrack({", f"  id: {js(TRACK['id'])},", f"  name: {js(TRACK['name'])},", f"  sub: {js(TRACK['sub'])},", "  lessons: ["]
for title, goal, about, terms in LESSONS:
    code = CODE[title]
    for k, *_ in terms:
        if k is not None and not whole(k, code):
            sys.exit(f"{title}: term key {k!r} is not in the code")
    lines += ["    {", '      lang: "python",', f"      file: {js(TRACK['file'])},", f"      t: {js(title)},", f"      goal: {js(goal)},",
              f"      code: {tpl(code)},", f"      about: {js(about)},", "      terms: ["]
    lines += [f"        [{'null' if k is None else js(k)}, {js(a)}, {js(b)}]," for k, a, b in terms]
    lines += ["      ],", f"      out: {tpl(outs[title])},", "    },"]
lines += ["  ],", "});", ""]
text = "\n".join(lines)
target = ROOT / "site/data/tracks/12-tpm.js"
if "--check" in sys.argv:
    same = target.exists() and target.read_text() == text
    print("12-tpm.js is current" if same else "12-tpm.js is stale: run python3 build12.py")
    sys.exit(0 if same else 1)
target.write_text(text)
print(f"wrote {target.relative_to(ROOT)}: {len(LESSONS)} steps")
